"""Éducation civique et santé publique de base (Cameroun) : symboles, droits et devoirs, route, environnement, maladies, hygiène, nutrition, secours."""
from .cult_kit import rows, table, theme

theme("civic-sante", "Éducation civique et santé publique de base",
      "Comparer avec la Constitution du 18 janvier 1996, le Code électoral, les programmes d'éducation civique (MINEDUB, MINESEC), la Convention relative aux droits de l'enfant (ONU, 1989), "
      "et pour la santé avec les fiches de l'OMS, de l'UNICEF et du ministère de la Santé publique du Cameroun (messages éducatifs, pas de conseil médical individuel).")

