    (2, "Quelle pandémie a commencé fin 2019 et touché le monde entier ?", "La COVID-19", ["Le choléra", "La polio", "La rougeole", "La dengue"], "L'OMS l'a qualifiée de pandémie le 11 mars 2020."),
    (4, "À quelle date l'OMS a-t-elle déclaré la COVID-19 pandémie ?", "Le 11 mars 2020", ["Le 1er janvier 2020", "Le 7 avril 2020", "Le 15 octobre 2020", "Le 3 mars 2021"], "L'annonce a été faite à Genève."),
    (2, "Quel geste barrière aide à limiter les maladies respiratoires ?", "Se couvrir la bouche en toussant ou éternuant", ["Cracher par terre", "Tousser sur ses voisins", "Se serrer fort la main", "Partager les verres"], "On tousse dans le pli du coude."),
    (3, "Quel geste de politesse limite la propagation des microbes ?", "Tousser dans son coude", ["Tousser dans la main puis serrer d'autres mains", "Tousser en face de quelqu'un", "Ne rien faire", "Tousser sur la nourriture"], "Il évite de contaminer les mains."),
